{
  "understanding": {
    "purpose": "2023년과 2024년의 주요 아파트 단지별 전용면적과 최저·최고 실거래가를 비교하는 표다.",
    "reading": "독자는 단지명으로 행을 찾고 면적을 확인한 뒤, 같은 행에서 연도별 최저가와 최고가를 가로로 비교한다. 가격 열의 폭과 줄바꿈 방식이 비슷하면 세로 비교도 쉬워진다.",
    "groups": [
      "단지명과 전용면적은 거래 대상을 식별한다.",
      "2023년의 최저·최고와 2024년의 최저·최고는 같은 역할을 하는 두 쌍이므로 가능한 한 같은 폭과 리듬을 유지한다."
    ],
    "keep_intact": [
      "면적 숫자와 ㎡ 단위",
      "가격을 구성하는 각 숫자와 억 단위",
      "연도와 최저·최고 머리글"
    ],
    "may_wrap": [
      "긴 단지명은 자연스러운 어절 경계에서 줄바꿈할 수 있다.",
      "가격은 억 단위 뒤 공백에서 두 줄로 나눌 수 있다.",
      "가격이 두 줄이 되는 행에서는 같은 행의 긴 단지명도 추가 행 높이 없이 줄바꿈할 수 있다."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [108, 75, 65, 65, 65, 64],
      "idea": "단지명과 면적에 여유를 주면서 네 가격 열을 거의 같은 폭으로 유지해 행 식별과 연도별 비교의 균형을 잡는다."
    },
    {
      "name": "B",
      "widths": [90, 66, 72, 72, 71, 71],
      "idea": "단지명과 면적을 압축하고 가격 열에 더 많은 공간을 배분해 네 가격 열의 가독성과 비교 리듬을 우선한다."
    },
    {
      "name": "C",
      "widths": [126, 66, 62, 62, 63, 63],
      "idea": "단지명을 한 줄로 유지할 수 있도록 폭을 확보하고 가격은 네 열에서 일관되게 줄바꿈하도록 한다."
    }
  ]
}
